1	/*******************************************************************************
2	 * Function:  Packet-->Memory Mapped Transaction Converter
3	 * Author:    Andreas Olofsson
4	 * License:   MIT (see LICENSE file in OH! repository)
5	 *
6	 * Documentation:
7	 *
8	 * see ./emesh_pack.v for packet formatting
9	 *
10	 ******************************************************************************/
11	module emesh_unpack
12	  #(parameter AW = 32,   // address width
13	    parameter PW = 104)  // packet width
14	   (
15	    //Input packet
16	    input [PW-1:0]    packet_in,
17	    //Write
18	    output 	      cmd_write,//start write
19	    output 	      cmd_write_stop,//stop burst
20	    //Read
21	    output 	      cmd_read,
22	    //Atomic read/write
23	    output 	      cmd_atomic_add,
24	    output 	      cmd_atomic_and,
25	    output 	      cmd_atomic_or,
26	    output 	      cmd_atomic_xor,
27	    output 	      cmd_cas,
28	    //Command Fields
29	    output [3:0]      cmd_opcode,//raw opcode
30	    output [3:0]      cmd_length,//bust length(up to 16)
31	    output [2:0]      cmd_size,//size of each transfer
32	    output [7:0]      cmd_user, //user field
33	    //Address/Data
34	    output [AW-1:0]   dstaddr, // read/write target address
35	    output [AW-1:0]   srcaddr, // read return address
36	    output [2*AW-1:0] data     // write data
37	    );
38	
39	   wire [15:0] cmd;
40	
41	   //############################################
42	   // Command Decode
43	   //############################################
44	
45	   emesh_decode emesh_decode (//Input
46				      .cmd_in		(cmd[15:0]),
47				      // Outputs
48				      .cmd_write	(cmd_write),
49				      .cmd_write_stop	(cmd_write_stop),
50				      .cmd_read		(cmd_read),
51				      .cmd_cas		(cmd_cas),
52				      .cmd_atomic_add	(cmd_atomic_add),
53				      .cmd_atomic_and	(cmd_atomic_and),
54				      .cmd_atomic_or	(cmd_atomic_or),
55				      .cmd_atomic_xor	(cmd_atomic_xor),
56				      .cmd_opcode	(cmd_opcode[3:0]),
57				      .cmd_user		(cmd_user[7:0]),
58				      .cmd_length	(cmd_length[3:0]),
59				      .cmd_size		(cmd_size[2:0]));
60	   generate
61	      //######################
62	      // 16-Bit ("lite/apb like")
63	      //######################
64	      if(AW==16) begin : aw16
65		 if(PW==40) begin : p40
66		    assign cmd[7:0]      = packet_in[7:0];
67		    assign cmd[15:8]     = 8'b0;
68		    assign dstaddr[15:0] = packet_in[23:8];
69		    assign srcaddr[15:0] = packet_in[39:24];
70		    assign data[31:0]    = {16'b0,packet_in[39:24]};
71		 end
72		 else begin: perror
73		    initial
74		      $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
75		 end
76	      end // block: aw16
77	      //######################
78	      // 32-Bit
79	      //######################
80	      if(AW==32) begin : aw32
81		if(PW==80) begin: p80
82		   assign cmd[15:0]     = packet_in[15:0];
83		   assign dstaddr[31:0] = packet_in[47:16];
84		   assign srcaddr[31:0] = packet_in[79:48];
85		   assign data[31:0]    = packet_in[79:48];
86		   assign data[63:32]   = 32'b0;
87		end
88		else if(PW==112) begin: p112
89		   assign cmd[15:0]     = packet_in[15:0];
90		   assign dstaddr[31:0] = packet_in[47:16];
91		   assign srcaddr[31:0] = packet_in[79:48];
92		   assign data[63:0]    = packet_in[111:48];
93		end
94		else begin: perror
95		   initial
96		     $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
97		end
98	      end // block: aw32
99	      //######################
100	      // 64-Bit
101	      //######################
102	      if(AW==64) begin : aw64
103		 if(PW==144) begin: p144
104		    assign cmd[15:0]      = packet_in[15:0];
105		    assign dstaddr[31:0]  = packet_in[47:16];
106		    assign srcaddr[63:0]  = packet_in[111:48];
107		    assign data[127:0]    = packet_in[111:48];
108		    assign dstaddr[63:32] = packet_in[143:112];
109		    assign data[127:64]   = 64'b0;
110		 end
111		 else if(PW==208) begin: p208
112		    assign cmd[15:0]      = packet_in[15:0];
113		    assign dstaddr[31:0]  = packet_in[47:16];
114		    assign srcaddr[63:0]  = packet_in[111:48];
115		    assign data[63:0]     = packet_in[111:48];
116		    assign dstaddr[63:32] = packet_in[143:112];
117		    assign data[127:64]   = packet_in[207:144];
118		 end
119		 else begin: perror
120		    initial
121		      $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
122		 end
123	      end // block: aw64
124	      //######################
125	      // 128-Bit
126	      //######################
127	      if(AW==128) begin : aw128
128		if(PW==272) begin: p272
129		   assign cmd[15:0]       = packet_in[15:0];
130		   assign dstaddr[31:0]   = packet_in[47:16];
131		   assign srcaddr[63:0]   = packet_in[111:48];
132		   assign data[63:0]      = packet_in[111:48];
133		   assign dstaddr[63:32]  = packet_in[143:112];
134		   assign data[127:64]    = packet_in[207:144];
135		   assign srcaddr[127:64] = packet_in[207:144];
136		   assign dstaddr[127:64] = packet_in[271:208];
137		   assign data[255:128]   = 128'b0;
138		 end
139		else if(PW==400) begin: p400
140		   assign cmd[15:0]       = packet_in[15:0];
141		   assign dstaddr[31:0]   = packet_in[47:16];
142		   assign srcaddr[63:0]   = packet_in[111:48];
143		   assign data[63:0]      = packet_in[111:48];
144		   assign dstaddr[63:32]  = packet_in[143:112];
145		   assign data[127:64]    = packet_in[207:144];
146		   assign srcaddr[127:64] = packet_in[207:144];
147		   assign dstaddr[127:64] = packet_in[271:208];
148		   assign data[255:128]   = packet_in[399:272];
149		end
150		else begin: perror
151		   initial
152		     $display ("Combo not supported (PW=%ds AW==%ds)", PW,AW);
153		end
154	      end // block: aw128
155	   endgenerate
156	
157	endmodule // enoc_unpack
